import{_ as a,c as e,o as r,ae as s}from"./chunks/framework.BvcDoAct.js";const T=JSON.parse('{"title":"VitePress","description":"","frontmatter":{"title":"VitePress"},"headers":[],"relativePath":"scripts/output/0_INTRO/1_translated.md","filePath":"scripts/output/0_INTRO/1_translated.md"}'),p={name:"scripts/output/0_INTRO/1_translated.md"};function o(n,t,_,i,c,l){return r(),e("div",null,[...t[0]||(t[0]=[s('<h2 id="持续进化的每一天之下-镌刻着各自的信念——" tabindex="-1">持续进化的每一天之下，镌刻着各自的信念—— <a class="header-anchor" href="#持续进化的每一天之下-镌刻着各自的信念——" aria-label="Permalink to &quot;持续进化的每一天之下，镌刻着各自的信念——&quot;">​</a></h2><h2 id="一路追随-be-first-的-japan-送上的-从过去通往未来的长传式访谈" tabindex="-1">一路追随 BE:FIRST 的 JAPAN 送上的，从过去通往未来的长传式访谈 <a class="header-anchor" href="#一路追随-be-first-的-japan-送上的-从过去通往未来的长传式访谈" aria-label="Permalink to &quot;一路追随 BE:FIRST 的 JAPAN 送上的，从过去通往未来的长传式访谈&quot;">​</a></h2><p>2021 年，从选拔企划《THE FIRST》诞生的 BE:FIRST，于 11 月 3 日迎来了主流出道 4 周年。在那之前不久的 10 月 29 日发行的，是组合首张精选专辑《BE:ST》。4 年就出精选——放在一般艺人身上，或许会让人觉得有些早；但当你看着曲目表里排开的 30 多首歌，就会明白这件事顺理成章。刻在这里的这些丰富而多样的作品，正是他们高密度岁月的足迹，也是进化的证明。</p><p>4 年前，在事务所社长兼制作人 SKY-HI 的引导下起步的 BE:FIRST，如今已经带着健康的自由感与贪婪的好奇心，靠自己的双脚不断跃上新的台阶。从巨蛋巡演到世界巡演，再到体育场公演，演出规模一路扩张，这就是最直接的证据。更重要的是，在这背后，成员们亲自积极参与歌曲制作，一路把「当下需要的声音」握在自己手里并将其实现。《BE:1》的主打曲《Scream》中有一句歌词——「去证明何为最高吧」，而他们也正如这句宣言所说，一边不断更新「最高」的定义，一边持续把它证明到了今天。</p><p>在《BE:ST》这个节点策划 BE:FIRST 特集时，我们最想做的一件事，就是去解开那段耀眼历史背后：每一位成员当时究竟在想什么。</p><p>作为最强进化集团 BE:FIRST 而活，他们到底改变了什么，又是如何一路保持不变的——其实在《rockin&#39;on JAPAN》，从《BE:1》发行后的 2022 年秋天起，我们就用了约半年的时间，进行了成员个人采访连载。这次别册特集中，我们一边摘录他们当时各自说过的话，一边尝试做一次访谈，再次触碰他们内里流动的信念（另外，各采访页面也重新刊载了 3 年前报道中的旧照片，也请关注他们在这些画面里的变化）。</p><p>为什么 BE:FIRST 会是 BE:FIRST？为什么他们能持续证明「最高」？</p><p>我想，这会是一组能够触及其真髓、独一无二的特集。 <br><br></p><p>（安田季那子）</p><p>采访＝小川智宏 摄影＝大野隼男</p><hr>',11)])])}const S=a(p,[["render",o]]);export{T as __pageData,S as default};
